    ({ bool _AssertPred = CONFIG_T::pool_width == CONFIG_T::stride_width; __builtin_assume(_AssertPred); });

    typename CONFIG_T::accum_t data_window[CONFIG_T::n_filt];
#pragma HLS ARRAY_PARTITION variable=data_window complete

